const inputItems = $input.all();
const normalizedItems = $('Classify Image Input Mode').all();
const outputItems = [];

const passthroughKeys = [
  'taskIndex', 'sceneIndex', 'sceneKey', 'sceneTitle', 'title', 'titleDescription',
  'taskDir', 'promptFileName', 'promptFilePath', 'productDetailFileName',
  'productDetailFilePath', 'rootOutputDir', 'productName', 'productDescription',
  'productAppearance', 'targetPlatform', 'targetMarket', 'ratio', 'timestamp',
  'workflowId', 'n8nExecutionId', 'sourceSubmissionId', 'viewImageMeta', 'sourceViewImages',
  'batchIndex', 'generationConcurrency', 'originalIndex', 'imageInputMode'
];

function text(value) {
  return value === undefined || value === null ? '' : String(value);
}

function isHttpUrl(value) {
  return /^https?:\/\//i.test(text(value).trim());
}

for (let itemIndex = 0; itemIndex < inputItems.length; itemIndex++) {
  const item = inputItems[itemIndex];
  const binary = item.binary || {};
  const source = normalizedItems[itemIndex]?.json || {};
  const prompt = text(source.prompt).trim();
  const negativePrompt = text(source.negativePrompt).trim();

  if (!prompt) {
    throw new Error(
      'Prepare Jimeng Image Input: missing prompt for itemIndex=' + itemIndex +
      ', taskIndex=' + text(source.taskIndex) +
      ', sceneKey=' + text(source.sceneKey) +
      ', originalIndex=' + text(source.originalIndex)
    );
  }

  const images = [];
  const images_base64 = [];
  const image_meta = [];

  if (source.imageInputMode === 'url') {
    for (let i = 1; i <= 5; i++) {
      const key = 'image-' + i;
      const url = text(source[key]).trim();
      if (!url) continue;
      if (!isHttpUrl(url)) throw new Error('Invalid HTTP image URL in ' + key + ' for itemIndex=' + itemIndex);
      images.push(url);
      image_meta.push({ key: 'image_' + i, source: 'siliconflow-url', url });
    }
  } else {
    for (let i = 1; i <= 5; i++) {
      const key = 'image_' + i;
      const bin = binary[key];
      if (!bin) continue;

      const mimeType = bin.mimeType || 'image/png';
      let buffer;
      try {
        buffer = await this.helpers.getBinaryDataBuffer(itemIndex, key);
      } catch (error) {
        if (bin.data && typeof bin.data === 'string') {
          const rawBase64 = bin.data.replace(/^data:[^;]+;base64,/, '');
          buffer = Buffer.from(rawBase64, 'base64');
        } else {
          throw new Error('Cannot read binary field ' + key + ': ' + error.message);
        }
      }

      const base64 = buffer.toString('base64');
      images.push('data:' + mimeType + ';base64,' + base64);
      images_base64.push(base64);
      image_meta.push({
        key,
        source: 'local-base64',
        mimeType,
        fileName: bin.fileName || (key + '.' + (bin.fileExtension || 'png')),
        fileExtension: bin.fileExtension || '',
        fileSize: buffer.length,
      });
    }
  }

  if (!images.length) {
    throw new Error(
      'No images were prepared for itemIndex=' + itemIndex +
      ', taskIndex=' + text(source.taskIndex) +
      ', sceneKey=' + text(source.sceneKey) +
      ', imageInputMode=' + text(source.imageInputMode)
    );
  }

  const passthrough = {};
  for (const key of passthroughKeys) {
    if (source[key] !== undefined) passthrough[key] = source[key];
  }

  outputItems.push({
    json: {
      ...passthrough,
      prompt,
      negativePrompt,
      model: source.model || 'jimeng-4.5',
      resolution: source.resolution || '2k',
      ratio: source.ratio || '1:1',
      images,
      images_base64,
      image_count: images.length,
      image_meta,
    },
    pairedItem: { item: itemIndex },
  });
}

return outputItems;

const root = $input.first()?.json || {};
const sourceItems = Array.isArray(root.batchItems) && root.batchItems.length ? root.batchItems : [root];
const hardLimit = 7;
const requestedLimit = Number(root.generationConcurrency ?? hardLimit);
const limit = Math.max(1, Math.min(sourceItems.length, hardLimit, Number.isFinite(requestedLimit) ? requestedLimit : hardLimit));

function pick(task, names, fallback = '') {
  for (const name of names) {
    const value = task?.[name];
    if (value !== undefined && value !== null && String(value).trim() !== '') return value;
  }
  return fallback;
}

const rootPrompt = pick(root, ['prompt', 'imagePrompt', 'mainPrompt'], '');
const rootNegativePrompt = pick(root, ['negativePrompt', 'negative_prompt', 'negative'], '');
const rootModel = pick(root, ['model'], 'jimeng-4.5');
const rootResolution = pick(root, ['resolution'], '2k');
const rootRatio = pick(root, ['ratio'], '1:1');

return sourceItems.slice(0, limit).map((task, index) => {
  const imageCount = Number(task.image_count ?? task.imageCount ?? task.viewImages?.length ?? 5);
  const incomingOriginalIndex = Number(task.originalIndex);
  const originalIndex = Number.isFinite(incomingOriginalIndex) ? incomingOriginalIndex : index;

  return {
    json: {
      ...task,
      originalIndex,
      'image-1': pick(task, ['image-1', 'viewImageAdd1']),
      'image-2': pick(task, ['image-2', 'viewImageAdd2']),
      'image-3': pick(task, ['image-3', 'viewImageAdd3']),
      'image-4': pick(task, ['image-4', 'viewImageAdd4']),
      'image-5': pick(task, ['image-5', 'viewImageAdd5']),
      prompt: pick(task, ['prompt', 'imagePrompt', 'mainPrompt', 'scenePrompt'], rootPrompt),
      negativePrompt: pick(task, ['negativePrompt', 'negative_prompt', 'negative'], rootNegativePrompt),
      model: pick(task, ['model'], rootModel),
      resolution: pick(task, ['resolution'], rootResolution),
      ratio: pick(task, ['ratio'], rootRatio),
      image_count: Number.isFinite(imageCount) ? imageCount : 5,
      batchIndex: index,
      generationConcurrency: limit,
    },
    pairedItem: { item: 0 },
  };
});

const items = $input.all();

function cleanString(value) {
  return String(value ?? '').trim();
}

function isHttpUrl(value) {
  return /^https?:\/\//i.test(cleanString(value));
}

const classified = items.map((item, index) => {
  const json = item.json || {};
  const values = [];
  for (let imageIndex = 1; imageIndex <= 5; imageIndex++) {
    const value = cleanString(json['image-' + imageIndex]);
    if (value) values.push(value);
  }
  if (!values.length) {
    throw new Error('No image inputs found for item ' + (index + 1));
  }
  const urlCount = values.filter(isHttpUrl).length;
  if (urlCount > 0 && urlCount !== values.length) {
    throw new Error('Mixed local paths and HTTP image URLs are not supported within one task at item ' + (index + 1));
  }
  return {
    json: {
      ...json,
      imageInputMode: urlCount === values.length ? 'url' : 'file',
    },
    pairedItem: item.pairedItem || { item: index },
  };
});

const modes = [...new Set(classified.map((item) => item.json.imageInputMode))];
if (modes.length !== 1) {
  throw new Error('A single S003 batch cannot mix URL-mode tasks and local-file tasks.');
}

return classified;

const items = $input.all().map((item) => item.json || {});
const completionPolicy = Object.freeze({ targetImageCount: 4, minimumSuccessImageCount: 1, attemptTimeoutMs: 300000, partialTerminalGraceMs: 30000 });
const pollIntervalSeconds = 10;
const attemptPreparedAtMs = Date.now();

if (items.length < 1 || items.length > 7) {
  throw new Error('S003 async submit expects 1-7 tasks, received ' + items.length + '.');
}

function text(value) {
  return value === undefined || value === null ? '' : String(value).trim();
}

function extensionFor(image, meta) {
  const explicit = text(meta?.fileExtension).replace(/^\./, '').toLowerCase();
  if (/^(png|jpe?g|webp)$/.test(explicit)) return explicit === 'jpeg' ? 'jpg' : explicit;
  const mime = text(meta?.mimeType).toLowerCase();
  if (mime.includes('jpeg')) return 'jpg';
  if (mime.includes('webp')) return 'webp';
  if (mime.includes('png')) return 'png';
  if (/^https?:\/\//i.test(image)) {
    try {
      const match = new URL(image).pathname.match(/\.([a-z0-9]+)$/i);
      if (match && /^(png|jpe?g|webp)$/i.test(match[1])) return match[1].toLowerCase() === 'jpeg' ? 'jpg' : match[1].toLowerCase();
    } catch (error) {}
  }
  return 'png';
}

const first = items[0];
const n8nExecutionId = text(first.n8nExecutionId);
const suppliedSubmissionId = text(first.sourceSubmissionId);
const sourceSubmissionId = suppliedSubmissionId || (n8nExecutionId
  ? (items.length === 7 ? 'E003:' : 'S003:') + n8nExecutionId
  : 'S003:' + String($execution.id || 'unknown'));

const images = Array.isArray(first.images) ? first.images.map(text).filter(Boolean) : [];
if (images.length < 1 || images.length > 10) {
  throw new Error('S003 async submit requires 1-10 prepared images.');
}
if (images.some((value) => !/^https?:\/\//i.test(value) && !/^data:image\/(?:png|jpe?g|webp);base64,/i.test(value))) {
  throw new Error('S003 async submit images must be HTTP(S) URLs or image Data URLs.');
}

for (const [index, item] of items.entries()) {
  const itemImages = Array.isArray(item.images) ? item.images.map(text).filter(Boolean) : [];
  if (JSON.stringify(itemImages) !== JSON.stringify(images)) {
    throw new Error('All S003 batch tasks must use the same ordered reference images; mismatch at item ' + (index + 1) + '.');
  }
}

const imageMeta = Array.isArray(first.image_meta) ? first.image_meta : [];
const sourceImages = images.map((image, index) => {
  const meta = imageMeta[index] || {};
  const extension = extensionFor(image, meta);
  const providedName = text(meta.sourceFileName || meta.fileName);
  const sourceFileName = providedName && !/^https?:\/\//i.test(providedName)
    ? providedName.replace(/\\/g, '/').split('/').filter(Boolean).pop()
    : 'reference-image-' + String(index + 1).padStart(2, '0') + '.' + extension;
  return {
    sourceFileName,
    fileExtension: extension,
    mimeType: text(meta.mimeType) || ('image/' + (extension === 'jpg' ? 'jpeg' : extension)),
    fileSize: Number(meta.fileSize || 0),
    originalIndex: index,
  };
});

const requestedConcurrency = Number(first.generationConcurrency ?? 5);
const concurrency = Math.max(1, Math.min(5, Number.isFinite(requestedConcurrency) ? Math.floor(requestedConcurrency) : 5));
const seenOriginalIndexes = new Set();
const tasks = items.map((item, index) => {
  const prompt = text(item.prompt);
  if (!prompt) throw new Error('S003 async task ' + (index + 1) + ' is missing prompt.');
  const originalIndex = Number.isInteger(Number(item.originalIndex)) ? Number(item.originalIndex) : index;
  if (seenOriginalIndexes.has(originalIndex)) throw new Error('Duplicate S003 originalIndex: ' + originalIndex + '.');
  seenOriginalIndexes.add(originalIndex);
  const taskIndex = Number.isInteger(Number(item.taskIndex)) ? Number(item.taskIndex) : originalIndex + 1;
  const taskBaseId = ['S003', 'v1', sourceSubmissionId, 'task-' + taskIndex].join(':');
  return {
    ...item,
    taskBaseId,
    taskId: taskBaseId + ':attempt-0',
    idempotencyKey: taskBaseId + ':attempt-0',
    sourceSubmissionId,
    originalIndex,
    taskIndex,
    retryAttempt: 0,
    prompt,
    negativePrompt: text(item.negativePrompt),
    completionPolicy: { ...completionPolicy },
    attemptPreparedAtMs,
    sourceImages,
  };
});

return [{
  json: {
    batchKey: ['S003', 'v1', sourceSubmissionId, 'batch', 'attempt-0'].join(':'),
    phase: 'initial',
    concurrency,
    common: {
      sourceSubmissionId,
      model: text(first.model) || 'jimeng-4.5',
      ratio: text(first.ratio) || '1:1',
      resolution: text(first.resolution) || '2k',
      sampleStrength: 0.5,
    },
    images,
    sourceImages,
    tasks,
    completionPolicy,
    pollIntervalSeconds,
    originalTaskCount: tasks.length,
  },
}];

const response = $input.first()?.json || {};
const batch = $('Build Async Submit Batch').first().json || {};
const expectedCount = Number(batch.originalTaskCount || 0);
const pollIntervalSeconds = Math.max(1, Number(batch.pollIntervalSeconds || 10));
const fallbackStartedAtMs = Date.now();
const sourceByTaskId = new Map((batch.tasks || []).map((task) => [String(task.taskId || ''), task]));

function diagnostic(value) {
  const raw = typeof value === 'string' ? value : JSON.stringify(value || {});
  return String(raw).replace(/\b(?:https?|data):[^\s"'<>]+/gi, '[redacted-url]').replace(/\s+/g, ' ').slice(0, 1000);
}

function timestampMs(value) {
  const numeric = Number(value);
  if (Number.isFinite(numeric) && numeric > 0) return numeric < 100000000000 ? numeric * 1000 : numeric;
  const parsed = Date.parse(String(value || ''));
  return Number.isFinite(parsed) ? parsed : 0;
}

function urlKey(value) {
  const text = String(value || '').trim();
  if (!/^https?:\/\//i.test(text)) return '';
  try {
    const parsed = new URL(text);
    return parsed.protocol.toLowerCase() + '//' + parsed.host.toLowerCase() + parsed.pathname;
  } catch (error) {
    return text.split(/[?#]/, 1)[0];
  }
}

const referenceKeys = new Set((batch.images || []).map(urlKey).filter(Boolean));
function urlsOf(task) {
  const values = [
    ...(Array.isArray(task?.imageUrls) ? task.imageUrls : []),
    ...(Array.isArray(task?.image_urls) ? task.image_urls : []),
    ...(Array.isArray(task?.urls) ? task.urls : []),
  ];
  const output = [];
  const seen = new Set();
  for (const value of values) {
    const url = String(value || '').trim();
    const key = urlKey(url);
    if (!key || referenceKeys.has(key) || seen.has(key)) continue;
    seen.add(key);
    output.push(url);
  }
  return output;
}

function reasonOf(task) {
  return String(task?.completionReason || task?.context?.completionReason || task?.failCode || '').trim();
}

function normalizeTask(task, nowMs) {
  const source = sourceByTaskId.get(String(task?.taskId || '')) || {};
  const context = { ...source, ...(task?.context || {}) };
  const policy = context.completionPolicy || task?.completionPolicy || batch.completionPolicy || {};
  const attemptTimeoutMs = Math.max(1000, Number(policy.attemptTimeoutMs || 300000));
  const attemptStartedAtMs = timestampMs(task?.submittedAt) || timestampMs(task?.createdAt) ||
    timestampMs(task?.attemptStartedAtMs) || timestampMs(context.attemptStartedAtMs) ||
    timestampMs(context.attemptPreparedAtMs) || timestampMs(source.attemptPreparedAtMs) || fallbackStartedAtMs;
  const attemptDeadlineAtMs = attemptStartedAtMs + attemptTimeoutMs;
  const deadlineReached = nowMs >= attemptDeadlineAtMs;
  const status = String(task?.status || '');
  const urls = urlsOf(task);
  const targetImageCount = Math.max(1, Number(policy.targetImageCount || 4));
  const existingReason = reasonOf(task);
  const base = { ...task, context, attemptStartedAtMs, attemptDeadlineAtMs, deadlineReached };
  if (urls.length > 0 && (status === 'success' || status === 'failed' || deadlineReached)) {
    const successfulReason = urls.length >= targetImageCount ? 'target_image_count_reached' : 'partial_image_result';
    const completionReason = /^(?:zero_images|zero_images_timeout|status_unconfirmed_no_retry)$/.test(existingReason) ? successfulReason : (existingReason || successfulReason);
    return { ...base, status: 'success', count: urls.length, imageUrls: urls, failCode: '', errorMessage: '', completionReason };
  }
  if (status === 'failed' && urls.length === 0) {
    return { ...base, count: 0, imageUrls: [], completionReason: existingReason || String(task?.failCode || 'zero_images') || 'zero_images' };
  }
  if (status === 'submission_unknown') {
    return { ...base, count: 0, imageUrls: [], completionReason: existingReason || 'submission_unknown_no_retry' };
  }
  if (status === 'success' && urls.length === 0) {
    return { ...base, count: 0, imageUrls: [], completionReason: existingReason || 'status_unconfirmed_no_retry' };
  }
  if (deadlineReached) {
    return { ...base, count: urls.length, imageUrls: urls, completionReason: urls.length > 0 ? (existingReason || 'partial_image_result') : 'status_unconfirmed_no_retry' };
  }
  return { ...base, count: urls.length, imageUrls: urls, completionReason: existingReason };
}

let tasks;
let submitTransportWarning = '';
if (Array.isArray(response.tasks)) {
  const code = String(response.code ?? '').trim();
  const accepted = response.ok === true || code === 'submission_unknown';
  if (!accepted) throw new Error('S003 async submit failed: ' + diagnostic(response));
  if (response.tasks.length !== expectedCount) throw new Error('S003 async submit returned ' + response.tasks.length + ' tasks; expected ' + expectedCount + '.');
  tasks = response.tasks;
} else if (response.ok === false && response.code) {
  throw new Error('S003 async submit failed before polling: ' + diagnostic(response));
} else {
  submitTransportWarning = diagnostic(response.error || response.message || response);
  tasks = (batch.tasks || []).map((task) => ({ taskId: task.taskId, idempotencyKey: task.idempotencyKey, status: 'reserved', historyId: '', context: task }));
}

const allowed = new Set(['reserved', 'processing', 'success', 'failed', 'submission_unknown']);
const historyRequired = new Set(['processing', 'success', 'failed']);
if (tasks.some((task) => !allowed.has(String(task?.status || '')) || (historyRequired.has(String(task?.status || '')) && !String(task?.historyId || '').trim()))) {
  throw new Error('S003 async submit returned an invalid task state: ' + diagnostic(tasks));
}
const nowMs = Date.now();
tasks = tasks.map((task) => normalizeTask(task, nowMs));
const terminal = new Set(['success', 'failed', 'submission_unknown']);
const allTerminal = tasks.every((task) => terminal.has(String(task.status || '')));
const terminalOrLimit = tasks.every((task) => terminal.has(String(task.status || '')) || Boolean(task.deadlineReached));
const taskStarts = tasks.map((task) => Number(task.attemptStartedAtMs)).filter(Number.isFinite);
const taskDeadlines = tasks.map((task) => Number(task.attemptDeadlineAtMs)).filter(Number.isFinite);

return [{ json: {
  ok: true,
  batchKey: batch.batchKey,
  phase: 'initial',
  tasks,
  taskCount: tasks.length,
  pollCount: 0,
  maxPollCount: Math.ceil(300000 / (pollIntervalSeconds * 1000)),
  pollIntervalSeconds,
  attemptStartedAtMs: taskStarts.length ? Math.min(...taskStarts) : fallbackStartedAtMs,
  attemptDeadlineAtMs: taskDeadlines.length ? Math.max(...taskDeadlines) : fallbackStartedAtMs + 300000,
  completionPolicy: batch.completionPolicy,
  remainingMs: taskDeadlines.length ? Math.max(0, Math.max(...taskDeadlines) - nowMs) : 300000,
  allTerminal,
  deadlineReached: terminalOrLimit && !allTerminal,
  pollLimitReached: terminalOrLimit && !allTerminal,
  terminalOrLimit,
  submitTransportWarning,
} }];

const input = $input.first()?.json || {};
const batch = $('Build Async Submit Batch').first().json || {};
const expectedCount = Number(batch.originalTaskCount || 0);
const sourceByTaskId = new Map((batch.tasks || []).map((task) => [String(task.taskId || ''), task]));
const statusQueryFailed = Boolean(input.error) || input.ok !== true || !Array.isArray(input.tasks);
let carriedState = input;
if (statusQueryFailed && !Array.isArray(carriedState.tasks)) {
  try { carriedState = $('Wait Initial Tasks').first().json || input; } catch (error) {}
}
let tasks = Array.isArray(carriedState.tasks) ? carriedState.tasks : [];
if (tasks.length !== expectedCount) throw new Error('S003 initial status query returned an unexpected task count: ' + tasks.length + '.');

function diagnostic(value) {
  const raw = typeof value === 'string' ? value : JSON.stringify(value || {});
  return String(raw).replace(/\b(?:https?|data):[^\s"'<>]+/gi, '[redacted-url]').replace(/\s+/g, ' ').slice(0, 1000);
}

function timestampMs(value) {
  const numeric = Number(value);
  if (Number.isFinite(numeric) && numeric > 0) return numeric < 100000000000 ? numeric * 1000 : numeric;
  const parsed = Date.parse(String(value || ''));
  return Number.isFinite(parsed) ? parsed : 0;
}

function urlKey(value) {
  const text = String(value || '').trim();
  if (!/^https?:\/\//i.test(text)) return '';
  try { const parsed = new URL(text); return parsed.protocol.toLowerCase() + '//' + parsed.host.toLowerCase() + parsed.pathname; }
  catch (error) { return text.split(/[?#]/, 1)[0]; }
}

const referenceKeys = new Set((batch.images || []).map(urlKey).filter(Boolean));
function urlsOf(task) {
  const values = [...(Array.isArray(task?.imageUrls) ? task.imageUrls : []), ...(Array.isArray(task?.image_urls) ? task.image_urls : []), ...(Array.isArray(task?.urls) ? task.urls : [])];
  const output = [];
  const seen = new Set();
  for (const value of values) {
    const url = String(value || '').trim();
    const key = urlKey(url);
    if (!key || referenceKeys.has(key) || seen.has(key)) continue;
    seen.add(key);
    output.push(url);
  }
  return output;
}

function reasonOf(task) { return String(task?.completionReason || task?.context?.completionReason || task?.failCode || '').trim(); }

function normalizeTask(task, nowMs) {
  const source = sourceByTaskId.get(String(task?.taskId || '')) || {};
  const context = { ...source, ...(task?.context || {}) };
  const policy = context.completionPolicy || task?.completionPolicy || batch.completionPolicy || {};
  const attemptTimeoutMs = Math.max(1000, Number(policy.attemptTimeoutMs || 300000));
  const attemptStartedAtMs = timestampMs(task?.submittedAt) || timestampMs(task?.createdAt) || timestampMs(task?.attemptStartedAtMs) || timestampMs(context.attemptStartedAtMs) || timestampMs(context.attemptPreparedAtMs) || timestampMs(source.attemptPreparedAtMs);
  if (!attemptStartedAtMs) throw new Error('S003 initial task is missing a stable submittedAt/createdAt attempt timestamp: ' + String(task?.taskId || 'unknown'));
  const attemptDeadlineAtMs = attemptStartedAtMs + attemptTimeoutMs;
  const deadlineReached = nowMs >= attemptDeadlineAtMs;
  const status = String(task?.status || '');
  const urls = urlsOf(task);
  const targetImageCount = Math.max(1, Number(policy.targetImageCount || 4));
  const existingReason = reasonOf(task);
  const base = { ...task, context, attemptStartedAtMs, attemptDeadlineAtMs, deadlineReached };
  if (urls.length > 0 && (status === 'success' || status === 'failed' || deadlineReached || statusQueryFailed)) {
    const successfulReason = urls.length >= targetImageCount ? 'target_image_count_reached' : 'partial_image_result';
    const completionReason = /^(?:zero_images|zero_images_timeout|status_unconfirmed_no_retry)$/.test(existingReason) ? successfulReason : (existingReason || successfulReason);
    return { ...base, status: 'success', count: urls.length, imageUrls: urls, failCode: '', errorMessage: '', completionReason };
  }
  if (status === 'failed' && urls.length === 0) return { ...base, count: 0, imageUrls: [], completionReason: existingReason || String(task?.failCode || 'zero_images') || 'zero_images' };
  if (status === 'submission_unknown') return { ...base, count: 0, imageUrls: [], completionReason: existingReason || 'submission_unknown_no_retry' };
  if (status === 'success' && urls.length === 0) return { ...base, count: 0, imageUrls: [], completionReason: existingReason || 'status_unconfirmed_no_retry' };
  if (statusQueryFailed || deadlineReached) return { ...base, count: 0, imageUrls: [], completionReason: 'status_unconfirmed_no_retry' };
  return { ...base, count: urls.length, imageUrls: urls, completionReason: existingReason };
}

const allowed = new Set(['reserved', 'processing', 'success', 'failed', 'submission_unknown']);
const historyRequired = new Set(['processing', 'success', 'failed']);
if (tasks.some((task) => !allowed.has(String(task?.status || '')) || (historyRequired.has(String(task?.status || '')) && !String(task?.historyId || '').trim()))) {
  throw new Error('S003 initial status query returned an invalid task state; no task will be resubmitted.');
}
const nowMs = Date.now();
tasks = tasks.map((task) => normalizeTask(task, nowMs));
const pollCount = Number(carriedState.pollCount || 0) + 1;
const terminal = new Set(['success', 'failed', 'submission_unknown']);
const allTerminal = tasks.every((task) => terminal.has(String(task.status || '')));
const terminalOrLimit = statusQueryFailed || tasks.every((task) => terminal.has(String(task.status || '')) || Boolean(task.deadlineReached));
const taskStarts = tasks.map((task) => Number(task.attemptStartedAtMs)).filter(Number.isFinite);
const taskDeadlines = tasks.map((task) => Number(task.attemptDeadlineAtMs)).filter(Number.isFinite);
return [{ json: {
  ...carriedState,
  ok: true,
  phase: 'initial',
  tasks,
  pollCount,
  maxPollCount: Math.ceil(300000 / (Math.max(1, Number(carriedState.pollIntervalSeconds || 10)) * 1000)),
  attemptStartedAtMs: Math.min(...taskStarts),
  attemptDeadlineAtMs: Math.max(...taskDeadlines),
  remainingMs: Math.max(0, Math.max(...taskDeadlines) - nowMs),
